"""Original transfusion medicine: thresholds, reactions and component selection."""
from qbank_authoring import question,ref,finalize
RB=ref('AABB International RBC Transfusion Guidelines, 2023','https://www.isbtweb.org/resource/red-blood-cell-transfusion-2023-aabb-international-guidelines.html')
MI=ref('AABB: Liberal Transfusion Strategy for Hospitalized Patients With AMI, 2025','https://www.aabb.org/news-resources/news/article/2025/08/20/expert-panel-recommends-liberal-transfusion-strategy-for-hospitalized-patients-with-ami')
PT=ref('AABB/ICTMG Platelet Transfusion Guidelines, 2025','https://www.aabb.org/news-resources/news/article/2025/05/29/aabb-develops-new-platelet-transfusion-guidelines')
RE=ref('Canadian Blood Services: Transfusion Reactions','https://professionaleducation.blood.ca/en/transfusion/clinical-guide/transfusion-reactions')
MO=ref('Canadian Blood Services: Irradiated, Washed and CMV-Seronegative Components','https://professionaleducation.blood.ca/en/transfusion/clinical-guide/irradiated-washed-and-cmv-seronegative-blood-components')
PL=ref('Canadian Blood Services: Platelet Transfusion and Refractoriness','https://professionaleducation.blood.ca/en/transfusion/clinical-guide/platelet-transfusion-alloimmunization-and-management-platelet')
rows=[]
def q(*a,**k):rows.append(question(*a,**k))
q('For most hemodynamically stable hospitalized adults without active bleeding or acute myocardial infarction, which hemoglobin level is the usual restrictive threshold to consider RBC transfusion?', 'Below 7 g/dL, interpreted with symptoms and clinical context',[
 ('Below 10 g/dL in every stable adult','A universal liberal threshold is not recommended for this population.'),('Below 12 g/dL whenever anemia is present','Mild anemia is not by itself an indication for RBC transfusion.'),('Below 5 g/dL as a mandatory minimum before any transfusion','This may dangerously delay treatment in many patients.')],
 'A restrictive strategy reduces unnecessary donor exposure in suitable populations', '**A threshold is a decision aid, not a replacement for clinical assessment.**',['Active hemorrhage and ischemia require separate reasoning.','Symptoms, trajectory and comorbidities affect the decision.'], '**Correct the cause of anemia alongside supportive treatment.**',['Transfusion does not replace iron or vitamin therapy when indicated.','In stable nonbleeding adults, reassess after each unit.'],[['Most stable adults','Consider below 7 g/dL'],['Clinical instability','Use resuscitation context'],['Underlying cause','Treat in parallel']],[RB])
q('Which statement reflects the 2025 AABB guidance for hospitalized patients with acute myocardial infarction and anemia?', 'A liberal RBC strategy when hemoglobin is below 10 g/dL is conditionally suggested, with individualized assessment',[
 ('The stable-adult 7 g/dL threshold is mandatory in every AMI patient','AMI has a separate recommendation.'),('Transfuse all AMI patients to above 15 g/dL','This is not the suggested strategy.'),('RBC transfusion is contraindicated throughout AMI','Selected patients may benefit and guidance does not impose that prohibition.')],
 'Acute myocardial ischemia has different oxygen-delivery considerations', '**AABB 2025 conditionally suggests a liberal approach below 10 g/dL in AMI.**',['The evidence certainty is low.','This is not a universal rule for all stable chronic cardiovascular disease.'], '**Balance oxygen delivery against transfusion complications.**',['Assess ongoing ischemia, bleeding and circulatory overload risk.','Use the recommendation within the full cardiac treatment plan.'],[['AMI','Separate 2025 recommendation'],['Threshold','Liberal strategy below 10 g/dL'],['Strength','Conditional, low-certainty evidence']],[MI])
q('A stable nonbleeding adult needs RBC support. Which prescribing approach generally best supports patient blood management?', 'Transfuse one unit and reassess the clinical response before ordering another',[
 ('Give four units automatically for every hemoglobin below normal','This can produce unnecessary exposure and overload.'),('Use plasma instead of RBCs to increase oxygen-carrying capacity','Plasma does not provide a clinically useful red-cell mass.'),('Normalize hemoglobin to 15 g/dL in every inpatient','Routine normalization is not the transfusion goal.')],
 'Each additional unit should have a clinical purpose', '**Single-unit reassessment is appropriate in stable nonbleeding adults.**',['Massive bleeding requires a different protocol.','Clinical response and hemoglobin trajectory guide further treatment.'], '**Combine judicious transfusion with diagnosis and treatment of anemia.**',['Avoid preventable phlebotomy loss.','Consider overload risk and the rate of administration.'],[['Stable nonbleeding','One unit then reassess'],['Major hemorrhage','Hemorrhage protocol'],['Goal','Adequate oxygen delivery, not routine normalization']],[RB])
q('An adult receiving chemotherapy has hypoproliferative thrombocytopenia, no bleeding and no additional risk factor. Below which platelet count is prophylactic transfusion generally recommended?', '10 × 10^9/L',[
 ('100 × 10^9/L','This would cause excessive prophylactic use in the stated setting.'),('50 × 10^9/L','This is a procedural threshold in selected settings, not the routine stable threshold.'),('150 × 10^9/L','A count below the reference range is not automatically a transfusion indication.')],
 'Platelet thresholds depend on mechanism and clinical setting', '**A restrictive prophylactic threshold is appropriate in selected hypoproliferative patients.**',['Bleeding, fever or procedures can change the plan.','This is not a blanket rule for ITP, TTP or every chronic low count.'], '**Use the current guideline population and context.**',['Assess response when ongoing support is needed.','Avoid unnecessary donor exposure.'],[['Stable hypoproliferation','Often below 10'],['Procedure','Procedure-specific threshold'],['Consumption or immune disease','Separate management pathway']],[PT])
q('Under the 2025 AABB/ICTMG guidance, what platelet transfusion threshold is recommended for a lumbar puncture in the relevant patient population?', 'Below 20 × 10^9/L',[
 ('Below 50 × 10^9/L as the unchanged universal AABB threshold','The 2025 recommendation uses a lower threshold for lumbar puncture.'),('Below 100 × 10^9/L for every lumbar puncture','That is not the 2025 routine threshold.'),('No platelet assessment is ever needed','Clinical bleeding risk still requires assessment.')],
 'Procedural recommendations evolve with evidence', '**The 2025 guideline recommends transfusion below 20 × 10^9/L for lumbar puncture.**',['This should not be automatically extrapolated to neurosurgery.','Anticoagulants, platelet dysfunction and other bleeding risks still matter.'], '**Follow the actual procedure-specific policy and patient assessment.**',['Use an experienced operator and appropriate technique.','Urgency and the broader risk profile can change management.'],[['Lumbar puncture','Below 20'],['Major nonneuraxial surgery','Different threshold'],['Neurosurgery','Do not extrapolate LP guidance']],[PT])
q('Which platelet threshold is generally used before major nonneuraxial surgery in an adult under the 2025 AABB/ICTMG recommendations?', 'Transfuse when below 50 × 10^9/L',[
 ('Below 10 × 10^9/L for every major operation','That is a stable prophylactic threshold, not the usual major-surgery threshold.'),('Below 150 × 10^9/L for all surgery','Routine normalization is not recommended.'),('The lumbar-puncture threshold applies unchanged to every operation','Procedure-specific bleeding consequences differ.')],
 'The consequence and controllability of surgical bleeding shape the threshold', '**Major nonneuraxial surgery has a different threshold from uncomplicated prophylaxis.**',['The platelet number is only one component of hemostasis.','Drug-induced dysfunction and coagulopathy need separate attention.'], '**Coordinate the hemostatic plan with the surgical and transfusion teams.**',['Neurosurgery and ophthalmic procedures may need separate local guidance.','Active massive bleeding requires dynamic assessment.'],[['Stable prophylaxis','Often 10'],['Lumbar puncture','20'],['Major nonneuraxial surgery','50 × 10^9/L']],[PT])
q('During an RBC transfusion, a patient develops fever, back pain, hypotension and dark urine. What is the immediate best action?', 'Stop the transfusion, maintain venous access with saline, support the patient and urgently notify the transfusion service',[
 ('Slow the infusion and continue the same unit without investigation','A potentially life-threatening reaction must be investigated.'),('Give an antipyretic and restart automatically','Fever may reflect hemolysis or sepsis, not a benign reaction.'),('Wait for the next routine hemoglobin before acting','Immediate assessment and supportive care are required.')],
 'Treat a suspected serious transfusion reaction as an emergency', '**Acute hemolysis and bacterial contamination must be considered.**',['Recheck patient and component identification.','Send the component and appropriate patient samples according to protocol.'], '**Support airway, circulation and renal perfusion while investigating.**',['Check hemolysis markers, DAT and compatibility as indicated.','Do not restart the implicated unit pending appropriate assessment.'],[['First','Stop transfusion'],['Parallel','Support and notify'],['Investigation','Identity, hemolysis, compatibility and cultures when indicated']],[RE],style='clinical_scenario')
q('Which mechanism classically causes a severe acute ABO-incompatible RBC transfusion reaction?', 'Recipient preformed antibodies activate complement against donor red cells, causing intravascular hemolysis',[
 ('A delayed primary IgG response arising only weeks later','That does not explain the immediate ABO reaction.'),('Donor T-cell engraftment as the immediate event','That causes transfusion-associated graft-versus-host disease on a different timeline.'),('Hydrostatic overload without red-cell destruction','That is TACO, not ABO-mediated hemolysis.')],
 'ABO incompatibility can destroy red cells rapidly', '**Preformed ABO antibodies can trigger complement-mediated intravascular hemolysis.**',['Hypotension, hemoglobinuria and DIC can occur.','Identification errors are a preventable cause.'], '**Bedside identity checking is a critical safety intervention.**',['Compatibility testing does not eliminate administration errors.','Urgent supportive care and transfusion-service investigation are essential.'],[['ABO antibody','Often pre-existing'],['Mechanism','Complement and hemolysis'],['Prevention','Correct patient and component identification']],[RE])
q('Eight days after transfusion, a patient develops jaundice, a falling hemoglobin and a new anti-Jka antibody. What is most likely?', 'Delayed hemolytic transfusion reaction from an anamnestic alloantibody response',[
 ('TACO','It presents with acute circulatory overload rather than this delayed hemolytic pattern.'),('Febrile nonhemolytic reaction','It does not explain delayed antibody-associated hemolysis.'),('Acute ABO incompatibility','Its characteristic presentation is during or soon after transfusion.')],
 'An evanescent antibody can reappear after antigen re-exposure', '**Kidd antibodies are a classic cause of delayed hemolysis.**',['A previously undetectable antibody can rise after transfusion.','DAT, antibody investigation and hemolysis markers support evaluation.'], '**Honor historical clinically significant antibodies.**',['Future RBC selection should avoid the implicated antigen.','Review outside transfusion records when available.'],[['Timing','Days to weeks'],['Mechanism','Anamnestic alloimmunity'],['Future units','Appropriate antigen-negative compatibility']],[RE],style='clinical_scenario')
q('A patient with heart failure develops dyspnea, hypertension, raised JVP and pulmonary edema after several transfused units; diuresis improves the symptoms. Which reaction best fits?', 'Transfusion-associated circulatory overload',[
 ('TRALI as the only diagnosis because pulmonary edema followed transfusion','Hydrostatic features and diuretic response favor TACO.'),('Acute hemolysis as established without hemolytic evidence','The presented findings primarily indicate overload.'),('Isolated urticaria','It does not cause this circulatory pattern.')],
 'Pulmonary edema after transfusion has more than one mechanism', '**TACO is principally hydrostatic circulatory overload.**',['Cardiac or renal disease and rapid or large-volume transfusion increase risk.','Surveillance definitions permit onset during or up to 12 hours after transfusion.'], '**Stop and assess the transfusion, provide respiratory support and treat overload.**',['Future prevention includes volume, rate and unit-by-unit reassessment.','TACO and other causes of lung injury can overlap.'],[['TACO','Hydrostatic overload'],['Clues','Hypertension, raised JVP and volume excess'],['Prevention','Appropriate dose and rate']],[RE],style='clinical_scenario')
q('A patient develops acute hypoxemia and bilateral pulmonary edema within four hours of transfusion, without hydrostatic overload as the main explanation. Which diagnosis should be considered?', 'Transfusion-related acute lung injury',[
 ('TACO is proven solely by bilateral infiltrates','Infiltrates alone do not identify a hydrostatic mechanism.'),('Delayed hemolysis','The timing and respiratory pattern differ.'),('Iron overload','This is a chronic cumulative complication rather than an acute lung injury.')],
 'TRALI is a clinical acute lung-injury diagnosis', '**Onset is during or within six hours of transfusion.**',['Donor leukocyte antibodies or other inflammatory mechanisms can contribute.','Patient inflammatory priming may increase susceptibility.'], '**Provide supportive respiratory care and notify the transfusion service.**',['Assess alternative ARDS risks and pretransfusion respiratory status.','Diuretics are not the primary treatment when hydrostatic overload is absent.'],[['Timing','Within six hours'],['Mechanism','Permeability lung injury'],['Management','Supportive care and investigation']],[RE],style='clinical_scenario')
q('A patient develops fever and rigors during platelet transfusion. Why should febrile nonhemolytic transfusion reaction initially remain a diagnosis of exclusion?', 'Hemolysis and bacterial contamination can produce a similar early presentation',[
 ('Every transfusion fever is caused by cytokines alone','Serious competing causes must be excluded.'),('Platelet products cannot transmit bacterial infection','Bacterial contamination is an important concern.'),('A normal baseline temperature excludes a septic reaction','It does not exclude newly introduced infection.')],
 'A common benign diagnosis must not hide a dangerous alternative', '**Stop and assess a new significant reaction before labeling it febrile nonhemolytic.**',['Review vital signs, identity and signs of hemolysis.','Culture the patient and component when sepsis is suspected.'], '**After exclusion, inflammatory mediators or leukocyte antibodies may explain FNHTR.**',['Leukoreduction reduces some febrile reactions.','Do not automatically restart a unit without appropriate assessment.'],[['FNHTR','Diagnosis after serious alternatives assessed'],['Hemolysis','Compatibility and hemolysis investigation'],['Sepsis','Cultures and urgent treatment when suspected']],[RE],style='clinical_scenario')

if __name__=='__main__':print('Transfusion medicine: '+str(len(rows))+' questions drafted')
